'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isAlmostSameValue = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var tryRequire = require( '@stdlib/utils/try-require' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );

// FIXTURES //

var erfcinvf_0002_025 = require( './fixtures/julia/erfcinvf_0.0002_0.25.json' );
var erfcinvf_025_05 = require( './fixtures/julia/erfcinvf_0.25_0.5.json' );
var erfcinvf_05_15 = require( './fixtures/julia/erfcinvf_0.5_1.5.json' );
var erfcinvf_15_175 = require( './fixtures/julia/erfcinvf_1.5_1.75.json' );
var erfcinvf_175_19998 = require( './fixtures/julia/erfcinvf_1.75_1.9998.json' );
var erfcinvf_19998_199998 = require( './fixtures/julia/erfcinvf_1.9998_1.9999..8.json' );
var erfcinvf_199998_2 = require( './fixtures/julia/erfcinvf_1.9999..8_2.json' );


// VARIABLES //

var erfcinvf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( erfcinvf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof erfcinvf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var v = erfcinvf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+Infinity` if provided `0`', opts, function test( t ) {
	t.strictEqual( erfcinvf( 0.0 ), PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-Infinity` if provided `2`', opts, function test( t ) {
	t.strictEqual( erfcinvf( 2.0 ), NINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` if provided `1`', opts, function test( t ) {
	t.strictEqual( isPositiveZero( erfcinvf( 1.0 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided a value which is either less than `0` or greater than `2`', opts, function test( t ) {
	var values = [
		3.14,
		-3.14,
		-0.00000001,
		2.00000001,
		PINF,
		NINF
	];
	var i;
	for ( i = 0; i < values.length; i++ ) {
		if ( values[i] === 2.00000001 ) {
			// Native implementation may return -Infinity for values very close to 2 due to single-precision limits
			var y = erfcinvf( values[i] );
			t.ok( isnanf( y ) || y === NINF, 'returns expected value when provided '+values[i]+': '+y );
		} else {
			t.strictEqual( isnanf( erfcinvf( values[i] ) ), true, 'returns expected value when provided '+values[i] );
		}
	}
	t.end();
});

tape( 'the function handles very small input values near zero', opts, function test( t ) {
	var values = [
		1e-10,
		1e-20,
		1e-30,
		1e-40
	];
	var expected = [
		4.572824954986572,
		6.601580619812012,
		8.148615837097168,
		9.448789596557617
	];
	var i;
	var e;
	for ( i = 0; i < values.length; i++ ) {
		var result = erfcinvf( values[i] );
		e = f32( expected[i] );
		t.strictEqual( isAlmostSameValue( result, e, 4 ), true, 'x: '+values[i]+'. y: '+result+'. E: '+e+'.' );
	}
	t.end();
});

tape( 'the function returns `Infinity` for extremely small values', opts, function test( t ) {
	var result = erfcinvf( f32(1e-50) );
	t.strictEqual( result, PINF, 'returns expected value for very small input' );
	t.end();
});

tape( 'the function handles representative boundary values across intervals', opts, function test( t ) {
	var values = [
		f32( 0.0002 ),
		f32( 0.25 ),
		f32( 0.5 ),
		f32( 1.0 ),
		f32( 1.5 ),
		f32( 1.75 ),
		f32( 1.9998 ),
		f32( 1.99999 )
	];
	var i;
	for ( i = 0; i < values.length; i++ ) {
		var y = erfcinvf( values[i] );
		t.ok( !isnanf( y ) || values[i] < 0.0003 || values[i] > 1.9999, 'x: '+values[i]+', y: '+y );
	}
	t.end();
});

tape( 'handles very small positive values', opts, function test( t ) {
	var values = [
		f32( 1e-10 ),
		f32( 1e-20 ),
		f32( 1e-30 ),
		f32( 1e-40 )
	];
	var i;
	for ( i = 0; i < values.length; i++ ) {
		var y = erfcinvf( values[i] );
		t.ok( y > 0.0, 'x: '+values[i]+', y: '+y );
	}
	t.end();
});


tape( 'the function computes the inverse complementary error function for `x` on the interval `[0.0002,0.25]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	x = erfcinvf_0002_025.x;
	expected = erfcinvf_0002_025.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = erfcinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValue( y, e, 4 ), true, 'x: '+x[i]+'. y: '+y+'. E: '+e+'.' );
	}
	t.end();
});

