tape( 'the function computes the inverse complementary error function for `x` on the interval `[1.99998,2]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	x = erfcinvf_199998_2.x;
	expected = erfcinvf_199998_2.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = erfcinvf( x[ i ] );
		e = f32( expected[ i ] );
		// Handle single-precision vs double-precision differences
		if ( y === -Infinity && ( expected[ i ] === null || ( expected[ i ] < -5.0 ) ) ) {
			t.strictEqual( y, -Infinity, 'x: '+x[i]+'. y: '+y+', expected: -Infinity (single-precision)' );
		} else if ( y === Infinity && ( expected[ i ] === null || ( expected[ i ] > 5.0 ) ) ) {
			t.strictEqual( y, Infinity, 'x: '+x[i]+'. y: '+y+', expected: Infinity (single-precision)' );
		} else if ( isnanf( y ) && ( expected[ i ] === null || isnanf( expected[ i ] ) ) ) {
			t.strictEqual( isnanf( y ), true, 'x: '+x[i]+'. y: '+y+', expected: NaN (single-precision)' );
		} else {
			t.strictEqual( isAlmostSameValue( y, e, 4 ), true, 'x: '+x[i]+'. y: '+y+'. E: '+e+'.' );
		}
	}
	t.end();
});
